233→// WriteTemporaryTask writes a task checkpoint to a shadow branch.
234→// Task checkpoints include both code changes and task-specific metadata.
235→// Returns the commit hash of the created checkpoint.
236→func (s *GitStore) WriteTemporaryTask(ctx context.Context, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
237→	// Validate base commit - required for shadow branch naming
238→	if opts.BaseCommit == "" {
239→		return plumbing.ZeroHash, errors.New("BaseCommit is required for task checkpoint")
240→	}
241→
242→	// Validate identifiers to prevent path traversal and malformed data
243→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
244→		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
245→	}
246→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
247→		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
248→	}
249→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
250→		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
251→	}
252→
253→	// Get shadow branch name
254→	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit, opts.WorktreeID)
255→
256→	// Get or create shadow branch
257→	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
258→	if err != nil {
259→		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
260→	}
261→
262→	// Collect all files to include in the commit
263→	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
264→	allFiles = append(allFiles, opts.ModifiedFiles...)
265→	allFiles = append(allFiles, opts.NewFiles...)
266→
267→	// Build new tree with code changes (no metadata dir yet)
268→	newTreeHash, err := s.buildTreeWithChanges(ctx, baseTreeHash, allFiles, opts.DeletedFiles, "", "")
269→	if err != nil {
270→		return plumbing.ZeroHash, fmt.Errorf("failed to build tree: %w", err)
271→	}
272→
273→	// Add task metadata to tree
274→	newTreeHash, err = s.addTaskMetadataToTree(ctx, newTreeHash, opts)
275→	if err != nil {
276→		return plumbing.ZeroHash, fmt.Errorf("failed to add task metadata: %w", err)
277→	}
278→
279→	// Create the commit
280→	commitHash, err := s.createCommit(newTreeHash, parentHash, opts.CommitMessage, opts.AuthorName, opts.AuthorEmail)
281→	if err != nil {
282→		return plumbing.ZeroHash, fmt.Errorf("failed to create commit: %w", err)
283→	}
284→
285→	// Update shadow branch reference
286→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
287→	ref := plumbing.NewHashReference(refName, commitHash)
288→	if err := s.repo.Storer.SetReference(ref); err != nil {
289→		return plumbing.ZeroHash, fmt.Errorf("failed to update shadow branch reference: %w", err)
290→	}
291→
292→	return commitHash, nil
293→}
