 706→// incrementalCheckpointData represents an incremental checkpoint during subagent execution.
 707→// This mirrors strategy.SubagentCheckpoint but avoids import cycles.
 708→type incrementalCheckpointData struct {
 709→	Type      string          `json:"type"`
 710→	ToolUseID string          `json:"tool_use_id"`
 711→	Timestamp time.Time       `json:"timestamp"`
 712→	Data      json.RawMessage `json:"data"`
 713→}
