 715→// taskCheckpointData represents a final task checkpoint.
 716→// This mirrors strategy.TaskCheckpoint but avoids import cycles.
 717→type taskCheckpointData struct {
 718→	SessionID      string `json:"session_id"`
 719→	ToolUseID      string `json:"tool_use_id"`
 720→	CheckpointUUID string `json:"checkpoint_uuid"`
 721→	AgentID        string `json:"agent_id,omitempty"`
