 724→// ReadCommitted reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
 725→// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
 726→// Use ReadSessionContent to read actual transcript/prompts/context.
 727→// Returns nil, nil if the checkpoint doesn't exist.
 728→//
 729→// The storage format uses numbered subdirectories for each session (0-based):
 730→//
 731→//	<checkpoint-id>/
 732→//	├── metadata.json      # CheckpointSummary with sessions map
 733→//	├── 0/                 # First session
 734→//	│   ├── metadata.json  # Session-specific metadata
 735→//	│   └── full.jsonl     # Transcript
 736→//	├── 1/                 # Second session
 737→//	└── ...
 738→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
 739→	if err := ctx.Err(); err != nil {
 740→		return nil, err //nolint:wrapcheck // Propagating context cancellation
 741→	}
 742→
 743→	ft, err := s.getFetchingTree(ctx)
 744→	if err != nil {
 745→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
 746→	}
 747→
 748→	checkpointPath := checkpointID.Path()
 749→	checkpointTree, err := ft.Tree(checkpointPath)
 750→	if err != nil {
 751→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
 752→	}
 753→
 754→	// Read root metadata.json as CheckpointSummary (auto-fetches blob if needed)
 755→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
 756→	if err != nil {
 757→		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
 758→	}
 759→
 760→	content, err := metadataFile.Contents()
 761→	if err != nil {
 762→		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
 763→	}
 764→
 765→	var summary CheckpointSummary
 766→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
 767→		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
 768→	}
 769→
 770→	return &summary, nil
 771→}
 772→
 773→// ReadSessionContent reads the actual content for a specific session within a checkpoint.
 774→// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
 775→// Returns the session's metadata, transcript, prompts, and context.
 776→// Returns an error if the checkpoint or session doesn't exist.
 777→func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
 778→	if err := ctx.Err(); err != nil {
 779→		return nil, err //nolint:wrapcheck // Propagating context cancellation
 780→	}
 781→
 782→	ft, err := s.getFetchingTree(ctx)
 783→	if err != nil {
 784→		return nil, ErrCheckpointNotFound
 785→	}
 786→
 787→	checkpointPath := checkpointID.Path()
 788→	checkpointTree, err := ft.Tree(checkpointPath)
 789→	if err != nil {
 790→		return nil, ErrCheckpointNotFound
 791→	}
 792→
 793→	// Get the session subdirectory
 794→	sessionDir := strconv.Itoa(sessionIndex)
 795→	sessionTree, err := checkpointTree.Tree(sessionDir)
 796→	if err != nil {
 797→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
 798→	}
 799→
 800→	result := &SessionContent{}
 801→
 802→	// Read session-specific metadata (auto-fetches blob if needed)
 803→	var agentType types.AgentType
 804→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
 805→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
 806→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
 807→				agentType = result.Metadata.Agent
 808→			}
 809→		}
 810→	}
 811→
 812→	// Read transcript (auto-fetches blobs if needed)
 813→	if transcript, transcriptErr := readTranscriptFromTree(ctx, sessionTree, agentType); transcriptErr == nil && transcript != nil {
 814→		result.Transcript = transcript
 815→	}
 816→
 817→	// Read prompts (auto-fetches blob if needed)
 818→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
 819→		if content, contentErr := file.Contents(); contentErr == nil {
 820→			result.Prompts = content
 821→		}
 822→	}
 823→
 824→	return result, nil
 825→}
 826→
 827→// ReadLatestSessionContent is a convenience method that reads the latest session's content.
 828→// This is equivalent to ReadSessionContent(ctx, checkpointID, len(summary.Sessions)-1).
 829→func (s *GitStore) ReadLatestSessionContent(ctx context.Context, checkpointID id.CheckpointID) (*SessionContent, error) {
 830→	summary, err := s.ReadCommitted(ctx, checkpointID)
 831→	if err != nil {
 832→		return nil, err
 833→	}
 834→	if summary == nil {
 835→		return nil, ErrCheckpointNotFound
 836→	}
 837→	if len(summary.Sessions) == 0 {
 838→		return nil, fmt.Errorf("checkpoint has no sessions: %s", checkpointID)
 839→	}
 840→
 841→	latestIndex := len(summary.Sessions) - 1
 842→	return s.ReadSessionContent(ctx, checkpointID, latestIndex)
 843→}
 844→
 845→// ReadSessionContentByID reads a session's content by its session ID.
 846→// This is useful when you have the session ID but don't know its index within the checkpoint.
 847→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
 848→// Returns an error if no session with the given ID exists in the checkpoint.
 849→func (s *GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
 850→	summary, err := s.ReadCommitted(ctx, checkpointID)
 851→	if err != nil {
 852→		return nil, err
 853→	}
 854→	if summary == nil {
 855→		return nil, ErrCheckpointNotFound
 856→	}
 857→
 858→	// Iterate through sessions to find the one with matching session ID
 859→	for i := range len(summary.Sessions) {
 860→		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
 861→		if readErr != nil {
 862→			continue
 863→		}
 864→		if content != nil && content.Metadata.SessionID == sessionID {
 865→			return content, nil
 866→		}
 867→	}
 868→
 869→	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
 870→}
 871→
 872→// ListCommitted lists all committed checkpoints from the entire/checkpoints/v1 branch.
 873→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
 874→//
 875→
 876→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
 877→	if err := ctx.Err(); err != nil {
 878→		return nil, err //nolint:wrapcheck // Propagating context cancellation
 879→	}
 880→
 881→	tree, err := s.getSessionsBranchTree()
 882→	if err != nil {
 883→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
 884→	}
 885→
 886→	var checkpoints []CommittedInfo
 887→
 888→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
 889→	for _, bucketEntry := range tree.Entries {
 890→		if bucketEntry.Mode != filemode.Dir {
 891→			continue
 892→		}
 893→		// Bucket should be 2 hex chars
 894→		if len(bucketEntry.Name) != 2 {
 895→			continue
 896→		}
 897→
 898→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
 899→		if treeErr != nil {
 900→			continue
 901→		}
 902→
 903→		// Each entry in the bucket is the remaining part of the checkpoint ID
 904→		for _, checkpointEntry := range bucketTree.Entries {
 905→			if checkpointEntry.Mode != filemode.Dir {
 906→				continue
 907→			}
 908→
 909→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
 910→			if cpTreeErr != nil {
 911→				continue
 912→			}
 913→
 914→			// Reconstruct checkpoint ID: <bucket><remaining>
 915→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
 916→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
 917→			if cpIDErr != nil {
 918→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
 919→				continue
 920→			}
 921→
 922→			info := CommittedInfo{
 923→				CheckpointID: checkpointID,
 924→			}
 925→
 926→			// Get details from root metadata file (CheckpointSummary format)
 927→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
 928→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
 929→					var summary CheckpointSummary
 930→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
 931→						info.CheckpointsCount = summary.CheckpointsCount
 932→						info.FilesTouched = summary.FilesTouched
 933→						info.SessionCount = len(summary.Sessions)
 934→
 935→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
 936→						if len(summary.Sessions) > 0 {
 937→							latestIndex := len(summary.Sessions) - 1
 938→							latestDir := strconv.Itoa(latestIndex)
 939→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
 940→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
 941→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
 942→										var sessionMetadata CommittedMetadata
 943→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
 944→											info.Agent = sessionMetadata.Agent
 945→											info.SessionID = sessionMetadata.SessionID
 946→											info.CreatedAt = sessionMetadata.CreatedAt
 947→										}
 948→									}
 949→								}
 950→							}
 951→						}
 952→					}
 953→				}
 954→			}
 955→
 956→			checkpoints = append(checkpoints, info)
 957→		}
 958→	}
 959→
 960→	// Sort by time (most recent first)
 961→	sort.Slice(checkpoints, func(i, j int) bool {
 962→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
 963→	})
 964→
 965→	return checkpoints, nil
 966→}
