508→// saveToFile saves settings to the specified file path.
509→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
510→	// Get absolute path for the file
511→	filePathAbs, err := paths.AbsPath(ctx, filePath)
512→	if err != nil {
513→		filePathAbs = filePath // Fallback to relative
514→	}
515→
516→	// Ensure directory exists
517→	dir := filepath.Dir(filePathAbs)
518→	if err := os.MkdirAll(dir, 0o750); err != nil {
519→		return fmt.Errorf("creating settings directory: %w", err)
520→	}
521→
522→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
523→	if err != nil {
524→		return fmt.Errorf("marshaling settings: %w", err)
525→	}
526→
527→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
528→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
529→		return fmt.Errorf("writing settings file: %w", err)
530→	}
531→	return nil
532→}
