429→// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
430→// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
431→type CheckpointRemoteConfig struct {
432→	Provider string // e.g., "github"
433→	Repo     string // e.g., "org/checkpoints-repo"
434→}
435→
436→// Owner returns the owner portion of the repo field (before the slash).
437→// Returns empty string if the repo field doesn't contain a slash.
438→func (c *CheckpointRemoteConfig) Owner() string {
439→	parts := strings.SplitN(c.Repo, "/", 2)
440→	if len(parts) < 2 {
441→		return ""
442→	}
443→	return parts[0]
444→}
445→
446→// GetCheckpointRemote returns the configured checkpoint remote.
447→// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
448→// Returns nil if not configured, wrong type, or missing required fields.
449→func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
450→	if s.StrategyOptions == nil {
451→		return nil
452→	}
453→	val, ok := s.StrategyOptions["checkpoint_remote"]
454→	if !ok {
455→		return nil
456→	}
457→	m, ok := val.(map[string]any)
458→	if !ok {
459→		return nil
460→	}
461→	provider, providerOK := m["provider"].(string)
462→	repo, repoOK := m["repo"].(string)
463→	if !providerOK || !repoOK || provider == "" || repo == "" {
464→		return nil
465→	}
466→	if !strings.Contains(repo, "/") {
467→		return nil
468→	}
469→	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
470→}
