132→	}
133→	pe, ok := ag.(PromptExtractor)
134→	if !ok {
135→		return nil, false
136→	}
137→	if cd, ok := ag.(CapabilityDeclarer); ok {
138→		return pe, cd.DeclaredCapabilities().TranscriptAnalyzer
139→	}
140→	return pe, true
141→}
142→
143→// AsSubagentAwareExtractor returns the agent as SubagentAwareExtractor if it both
144→// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
145→func AsSubagentAwareExtractor(ag Agent) (SubagentAwareExtractor, bool) { //nolint:ireturn // type-assertion helper must return interface
146→	if ag == nil {
147→		return nil, false
148→	}
149→	sae, ok := ag.(SubagentAwareExtractor)
150→	if !ok {
151→		return nil, false
152→	}
153→	if cd, ok := ag.(CapabilityDeclarer); ok {
154→		return sae, cd.DeclaredCapabilities().SubagentAwareExtractor
155→	}
156→	return sae, true
157→}
